(3368160, 466840, 63503, '<td valign="top">Beautiful</td>', 'Beautiful', '2007-02-15 00:44:00.000000', NULL, 1),
(3368165, 465563, 73799, '<td valign="top">This is the mangyiest gull I''ve seen in my life. Taking this picture was almost mean! Its like sneaking a snap shot of your wife right after she wakes up, no makeup, crumpled hair, groggy expression.  I just don''t think its very nice, you see?<br/> <br/>Nick</td>', 'This is the mangyiest gull I''ve seen in my life. Taking this picture was almost mean! Its like sneaking a snap shot of your wife right after she wakes up, no makeup, crumpled hair, groggy expression.  I just don''t think its very nice, you see? Nick', '2007-02-15 00:48:47.000000', NULL, 1),
(3368166, 468696, 63503, '<td valign="top">This is the most creative photograph in this challenge. The eye in the magnifying glass is spectacular and the color scheme is perfect. This would be a 10, were it not for the wrinkled backdrop (9)</td>', 'This is the most creative photograph in this challenge. The eye in the magnifying glass is spectacular and the color scheme is perfect. This would be a 10, were it not for the wrinkled backdrop (9)', '2007-02-15 00:48:55.000000', NULL, 1),
(3368168, 468307, 53316, '<td valign="top">I remember something incredibly like this from a class a while ago; I don''t ever remember doing mouse brains but I guess I did.  Anyway, very VERY awesome photo and just perfect for this challenge!</td>', 'I remember something incredibly like this from a class a while ago; I don''t ever remember doing mouse brains but I guess I did.  Anyway, very VERY awesome photo and just perfect for this challenge!', '2007-02-15 00:50:04.000000', NULL, 1),
(3368169, 468304, 63503, '<td valign="top">Should have been green. Dry fall leaves are no loger capable of photosynthesis.</td>', 'Should have been green. Dry fall leaves are no loger capable of photosynthesis.', '2007-02-15 00:50:19.000000', NULL, 1),
