(3536923, 468670, 29009, '<td valign="top">Ahhh, those were the days, back when everything was as simple as "I like you, do you like me?  Check Yes or No."  The shot sure could be in better focus, but I have a big smile on my face.  Thanks for posting to the Take Your Shame thread!</td>', 'Ahhh, those were the days, back when everything was as simple as "I like you, do you like me?  Check Yes or No."  The shot sure could be in better focus, but I have a big smile on my face.  Thanks for posting to the Take Your Shame thread!', '2007-04-10 23:19:34.000000', NULL, 0),
(3551707, 468336, 26001, '<td valign="top">excellent idea. i like the contrast between colored flower and bw printed-background. a very well deserved high-score.</td>', 'excellent idea. i like the contrast between colored flower and bw printed-background. a very well deserved high-score.', '2007-04-16 11:22:49.000000', NULL, 0),
(3569652, 467927, 25678, '<td valign="top">nice picture. I think a touch more light to bring out the details of the specimens would have bumped your score even higher<br/> <br/>Hope you got to dissect a few of those critters!</td>', 'nice picture. I think a touch more light to bring out the details of the specimens would have bumped your score even higher Hope you got to dissect a few of those critters!', '2007-04-21 23:27:46.000000', NULL, 0),
(3576558, 467646, 50171, '<td valign="top">pyf era e komve</td>', 'pyf era e komve', '2007-04-24 11:03:40.000000', NULL, 0),
